/* TIOM Mechanical ERP Integrated Workspace — single /tiom URL, no separate page. */
(function(){
const $=id=>document.getElementById(id);
const siteId='TIOM';
const state={bootstrap:null,ctx:null,dash:null,group:'DASHBOARD',tab:'DASHBOARD',workshopTab:'JOBS',equipmentTab:'HISTORY',components:[],services:[],componentSchedules:[],pmPlans:[],tyres:[],dashboardFilters:{from:'',to:'',asset:'',status:'',type:''},reportPreview:null};
const GROUPS=[
  ['DASHBOARD','Dashboard',[['DASHBOARD','Overview']]],
  ['ENTRY','Daily Entry',[['ENTRY','Single Entry']]],
  ['WORKSHOP','Workshop & Planning',[['JOBS','Breakdown / Jobs'],['SERVICE','Service'],['COMPONENTS','Components'],['PMPLAN','PM / WGP Plans'],['DEFCONFIG','DEF Schedule']]],
  ['TYRES','Tyres',[['TYRES','Tyre Management']]],
  ['EQUIPMENT','Equipment 360°',[['HISTORY','History'],['COMPLIANCE','Compliance']]],
  ['REPORTS','Reports',[['REPORTS','Reports & Export']]],
];
const TITLES={
  DASHBOARD:['Mechanical Dashboard','Live equipment status, due schedules and exceptions from shared TIOM ERP transactions.'],
  ENTRY:['Daily Maintenance Entry','One field entry point. Select equipment once, then record the maintenance event.'],
  JOBS:['Workshop Control','Breakdown queue and job-card closure in one workshop view.'],
  SERVICE:['Scheduled Service','Service planning driven by existing HMR/KMR and calendar schedules.'],
  COMPONENTS:['Component Change Schedule','Filters, oils and replaceable parts linked to service history and Stores references.'],
  PMPLAN:['PM / WGP Planning','Preventive maintenance, washing, greasing and inspection schedules.'],
  DEFCONFIG:['DEF / Urea Schedule','Equipment-wise DEF capacity, issue pattern and consumption alert configuration.'],
  TYRES:['Tyre Management','Tyre register, fitment and running-KM lifecycle.'],
  HISTORY:['Equipment 360°','One equipment history across meter, production-linked HMR/KMR, breakdown, jobs and DEF.'],
  COMPLIANCE:['Equipment Compliance','PUC, insurance, fitness, permit, AMC and warranty expiry.'],
  REPORTS:['Management Reports','Date-range Excel downloads from the same ERP transactions.']
};
async function api(url,opts={}){return NMTPLNet.json(url,opts)}
window.addEventListener('nmtpl-session-expired',()=>{location.href='/?expired=1'});
function esc(v){return String(v??'').replace(/[&<>'\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function fmt(n,d=0){return n===null||n===undefined?'—':Number(n).toLocaleString('en-IN',{maximumFractionDigits:d})}
function toast(m,t='good'){if(typeof window.toast==='function'){window.toast(m,t==='bad');return}const x=$('toast');if(!x)return;x.textContent=m;x.className=`toast on ${t}`;setTimeout(()=>x.className='toast',2800)}
function status(x){return `<span class="mech-status ${esc(x||'')}">${esc(String(x||'—').replaceAll('_',' '))}</span>`}
function panel(title,body,actions=''){return `<section class="panel mech-panel"><div class="mech-panel-head"><h3>${title}</h3><div>${actions}</div></div><div class="mech-panel-body">${body}</div></section>`}
function table(headers,rows){return `<div class="tablewrap mech-table-wrap"><table class="mech-table"><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.join(''):`<tr><td colspan="${headers.length}" class="mech-empty">No records found.</td></tr>`}</tbody></table></div>`}
function assetOptions(blank='Select equipment'){return `<option value="">${blank}</option>${(state.dash?.allAssets||state.dash?.assets||[]).map(x=>`<option value="${esc(x.assetId)}">${esc(x.display)} · ${esc(x.type||'')}</option>`).join('')}`}
function componentOptions(){return `<option value="">Select component</option>${state.components.map(x=>`<option value="${esc(x.componentId)}">${esc(x.componentName)}${x.partNumber?' · '+esc(x.partNumber):''}</option>`).join('')}`}
function tyreOptions(){return `<option value="">Select tyre</option>${state.tyres.filter(x=>x.status!=='FITTED').map(x=>`<option value="${esc(x.tyreId)}">${esc(x.serialNo)} · ${esc(x.brand||'')}</option>`).join('')}`}
function nowLocal(){const d=new Date(Date.now()-new Date().getTimezoneOffset()*60000);return d.toISOString().slice(0,16)}
function dateVal(d=new Date()){return d.toISOString().slice(0,10)}
function groupForTab(tab){for(const [g,,tabs] of GROUPS)if(tabs.some(x=>x[0]===tab))return g;return 'DASHBOARD'}
function renderNav(){
  const top=$('mech_top_tabs'), sub=$('mech_sub_tabs'); if(!top||!sub)return;
  top.innerHTML=GROUPS.map(([g,label])=>`<button class="${state.group===g?'active':''}" data-mech-group="${g}">${label}</button>`).join('');
  top.querySelectorAll('[data-mech-group]').forEach(b=>b.onclick=()=>{const g=b.dataset.mechGroup,info=GROUPS.find(x=>x[0]===g);state.group=g;if(!info[2].some(x=>x[0]===state.tab))state.tab=info[2][0][0];render()});
  const info=GROUPS.find(x=>x[0]===state.group)||GROUPS[0];
  sub.innerHTML=info[2].length>1?info[2].map(([k,l])=>`<button class="${state.tab===k?'active':''}" data-mech-tab="${k}">${l}</button>`).join(''):'';
  sub.hidden=info[2].length<=1;
  sub.querySelectorAll('[data-mech-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.mechTab;state.group=groupForTab(state.tab);render()});
}
function setHead(){const [t,s]=TITLES[state.tab]||[state.tab,''];if($('mech_title'))$('mech_title').textContent=t;if($('mech_subtitle'))$('mech_subtitle').textContent=s;if($('mech_context'))$('mech_context').innerHTML=`<span>TIOM</span><span>${state.dash?.operatingDate||''}</span><span>Shift ${state.dash?.shift||''}</span>`}
async function refreshDash(){
  const f=state.dashboardFilters||{}, q=new URLSearchParams();
  if(f.from)q.set('from_date',f.from);if(f.to)q.set('to_date',f.to);if(f.asset)q.set('asset_id',f.asset);if(f.status)q.set('status',f.status);if(f.type)q.set('equipment_type',f.type);
  state.dash=await api(`/api/maintenance/${siteId}/dashboard${q.toString()?'?'+q:''}`)
}
async function render(){
  renderNav();setHead();const out=$('mech_view');if(!out)return;out.innerHTML='<div class="loading">Loading…</div>';
  try{let h='';
    if(state.tab==='DASHBOARD')h=renderDashboard();
    else if(state.tab==='ENTRY')h=await renderQuickEntry();
    else if(state.tab==='JOBS')h=await renderWorkshopQueue();
    else if(state.tab==='SERVICE')h=await renderService();
    else if(state.tab==='COMPONENTS')h=await renderComponents();
    else if(state.tab==='PMPLAN')h=await renderPmPlanning();
    else if(state.tab==='DEFCONFIG')h=await renderDefConfig();
    else if(state.tab==='TYRES')h=await renderTyres();
    else if(state.tab==='HISTORY')h=renderHistory();
    else if(state.tab==='COMPLIANCE')h=await renderCompliance();
    else if(state.tab==='REPORTS')h=renderReports();
    out.innerHTML=h;
    if(state.tab==='ENTRY')quickEntryChanged();
  }catch(e){out.innerHTML=`<div class="bad"><b>Unable to load Mechanical.</b><br>${esc(e.message)}</div>`}
}
function quickAssetInfo(){const id=$('qeAsset')?.value;const a=(state.dash?.assets||[]).find(x=>x.assetId===id);const box=$('qeAssetInfo');if(!box)return;if(!a){box.innerHTML='Select equipment to see current ERP status and meter.';return}box.innerHTML=`<b>${esc(a.display)}</b> · ${status(a.status)} · ${esc(a.meterType||'Meter')} ${fmt(a.meterReading,1)} · ${esc(a.locationId||'Location —')} · ${esc(a.operatorId||'Operator —')}`}
function quickEntryFields(type){
  if(type==='BREAKDOWN')return `<div class="grid3"><label>Problem Category<select id="qeCat"><option>MECHANICAL</option><option>ENGINE</option><option>HYDRAULIC</option><option>ELECTRICAL</option><option>TYRE</option><option>BRAKE</option><option>OTHER</option></select></label><label class="mech-span2">Problem *<input id="qeProblem" placeholder="Short problem description"></label><label class="mech-span2">Remarks<input id="qeRemarks" placeholder="Optional"></label></div>`;
  if(type==='PM')return `<div class="grid3"><label>Activity<select id="qeActivity"><option>PM</option><option>WASHING</option><option>GREASING</option><option>INSPECTION</option></select></label><label>Result<select id="qeResult"><option>COMPLETE</option><option>PASS</option><option>FAIL</option></select></label><label>Linked Plan<select id="qePmPlan"><option value="">Auto / None</option>${state.pmPlans.map(x=>`<option value="${esc(x.pmPlanId)}">${esc(x.planName)}</option>`).join('')}</select></label><label class="mech-span2">Remarks<input id="qeRemarks" placeholder="Optional"></label></div>`;
  if(type==='DEF')return `<div class="grid3"><label>DEF Quantity (L) *<input id="qeQty" type="number" inputmode="decimal" step="0.001"></label><label>Issue Slip / Reference<input id="qeRef"></label><label>Remarks<input id="qeRemarks"></label></div>`;
  if(type==='SPARE')return `<div class="grid3"><label>Part / Spare *<input id="qePart"></label><label>Qty *<input id="qeQty" type="number" inputmode="decimal" step="0.001"></label><label>Unit<input id="qeUnit" value="NOS"></label><label>Store Issue Ref<input id="qeRef"></label><label>Job Card<input id="qeJob"></label></div>`;
  if(type==='LUBE')return `<div class="grid3"><label>Lubricant<select id="qeLube"><option>ENGINE OIL</option><option>HYDRAULIC OIL</option><option>TRANSMISSION OIL</option><option>GEAR OIL</option><option>GREASE</option><option>COOLANT</option><option>OTHER</option></select></label><label>Qty *<input id="qeQty" type="number" inputmode="decimal" step="0.001"></label><label>Unit<input id="qeUnit" value="L"></label><label>Job Card<input id="qeJob"></label></div>`;
  return '';
}
function quickEntryChanged(){const type=$('qeType')?.value||'BREAKDOWN';if($('qeFields'))$('qeFields').innerHTML=quickEntryFields(type);quickAssetInfo()}
async function renderQuickEntry(){
  if(!state.pmPlans.length){try{state.pmPlans=await api(`/api/maintenance/${siteId}/pm-plans`)}catch(_){state.pmPlans=[]}}
  return `<div class="panel mech-panel mech-entry-card"><div class="mech-panel-head"><div><h3>Daily Maintenance Entry</h3><div class="sub">Equipment is selected once. Shift, operator, location and latest HMR/KMR are reused from TIOM.</div></div></div><div class="mech-panel-body"><div class="grid3"><label>Equipment *<select id="qeAsset" onchange="quickAssetInfo()">${assetOptions()}</select></label><label>Entry Type *<select id="qeType" onchange="quickEntryChanged()"><option value="BREAKDOWN">Breakdown</option><option value="PM">PM / Washing / Greasing</option><option value="DEF">DEF / Urea</option><option value="SPARE">Spare Consumption</option><option value="LUBE">Lubricant Consumption</option></select></label></div><div id="qeAssetInfo" class="mech-auto-info">Select equipment to see current ERP status and meter.</div><div id="qeFields" class="mech-entry-fields"></div><div class="btnrow"><button class="btn primary" onclick="saveQuickEntry()">Save Entry</button><span class="note">No repeated equipment/HMR/shift entry.</span></div></div></div>${panel('ERP Linkage',`<div class="mech-flow"><span>Equipment Master</span><b>→</b><span>Production HMR/KMR</span><b>→</b><span>Maintenance Transaction</span><b>→</b><span>Status / Cost / History / Report</span></div>`)}`
}
async function saveQuickEntry(){
  try{
    const asset=$('qeAsset')?.value,type=$('qeType')?.value;if(!asset)throw new Error('Choose equipment.');
    if(type==='BREAKDOWN'){
      const problem=$('qeProblem')?.value.trim();if(!problem)throw new Error('Enter problem.');
      const r=await api(`/api/maintenance/${siteId}/breakdowns`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({assetId:asset,problemCategory:$('qeCat').value,problem,remarks:$('qeRemarks').value.trim()||null})});toast(`BD created · ${r.breakdownId}`);
    }else if(type==='PM'){
      await api(`/api/maintenance/${siteId}/pm-executions`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({assetId:asset,activity:$('qeActivity').value,pmPlanId:$('qePmPlan').value||null,result:$('qeResult').value,remarks:$('qeRemarks').value.trim()||null})});toast('PM/WGP activity completed');
    }else if(type==='DEF'){
      if(!+$('qeQty').value)throw new Error('Enter DEF quantity.');await api(`/api/maintenance/${siteId}/def`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({assetId:asset,quantityL:$('qeQty').value,issueReference:$('qeRef').value.trim()||null,remarks:$('qeRemarks').value.trim()||null})});toast('DEF issue saved');
    }else if(type==='SPARE'){
      if(!$('qePart').value.trim()||!+$('qeQty').value)throw new Error('Enter part and quantity.');await api(`/api/maintenance/${siteId}/spares`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({assetId:asset,description:$('qePart').value.trim(),quantity:$('qeQty').value,unit:$('qeUnit').value||'NOS',storeIssueReference:$('qeRef').value.trim()||null,jobCardId:$('qeJob').value.trim()||null})});toast('Spare consumption saved');
    }else if(type==='LUBE'){
      if(!+$('qeQty').value)throw new Error('Enter lubricant quantity.');await api(`/api/maintenance/${siteId}/lubricants`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({assetId:asset,lubricantType:$('qeLube').value,quantity:$('qeQty').value,unit:$('qeUnit').value||'L',jobCardId:$('qeJob').value.trim()||null})});toast('Lubricant consumption saved');
    }
    await refreshDash();render();
  }catch(e){toast(e.message,'bad')}
}
async function renderWorkshopQueue(){
  const [bds,jobs]=await Promise.all([api(`/api/maintenance/${siteId}/breakdowns?from_date=${dateVal(new Date(Date.now()-30*86400000))}&to_date=${dateVal()}`),api(`/api/maintenance/${siteId}/job-cards`)]);
  const open=bds.filter(x=>['OPEN','IN_PROGRESS'].includes(x.status));
  return panel('Open Breakdown Queue',table(['BD No.','Equipment','Reported','Problem','Meter','Status','Downtime','Action'],open.map(x=>`<tr><td>${esc(x.breakdownId)}</td><td>${esc(x.assetId)}</td><td>${new Date(x.reportedAt).toLocaleString('en-IN')}</td><td><b>${esc(x.problemCategory)}</b><br>${esc(x.problem)}</td><td>${esc(x.meterType||'')} ${fmt(x.meterReading,1)}</td><td>${status(x.status)}</td><td>${fmt(x.downtimeHours,2)}</td><td><button class="btn small primary" onclick="closeBreakdown('${esc(x.breakdownId)}')">Release</button></td></tr>`)))+
    panel('Job Cards',table(['Job Card','Equipment','Type','Opened','Status','Complaint','Mechanic','Action'],jobs.map(x=>`<tr><td>${esc(x.jobCardId)}</td><td>${esc(x.assetId)}</td><td>${esc(x.jobType)}</td><td>${new Date(x.openedAt).toLocaleString('en-IN')}</td><td>${status(x.status)}</td><td>${esc(x.complaint||'—')}</td><td>${esc(x.mechanicId||'—')}</td><td>${x.status==='OPEN'?`<button class="btn small secondary" onclick="jobStatus('${esc(x.jobCardId)}','IN_PROGRESS')">Start</button>`:''}${['OPEN','IN_PROGRESS','COMPLETED'].includes(x.status)?` <button class="btn small primary" onclick="releaseJob('${esc(x.jobCardId)}')">Complete</button>`:''}</td></tr>`))+`<details><summary>Create a general workshop job card</summary><div class="grid3 topgap"><label>Equipment *<select id="jcAsset">${assetOptions()}</select></label><label>Job Type<select id="jcType"><option>GENERAL</option><option>SERVICE</option><option>PM</option><option>TYRE</option><option>INSPECTION</option></select></label><label>Complaint / Work Required<input id="jcComplaint"></label></div><div class="btnrow"><button class="btn primary" onclick="saveJob()">Create Job Card</button></div></details>`)
}
async function renderPmPlanning(){
  state.pmPlans=await api(`/api/maintenance/${siteId}/pm-plans`);
  return panel('PM / WGP Plans',table(['Equipment','Activity','Plan','Basis','Next Due','Current','Status'],state.pmPlans.map(x=>`<tr><td>${esc(x.assetId||x.equipmentType||'Group')}</td><td>${esc(x.activity)}</td><td>${esc(x.planName)}</td><td>${esc(x.scheduleBasis)}</td><td>${x.nextDueMeter!=null?fmt(x.nextDueMeter,1):esc(x.nextDueAt||'—')}</td><td>${fmt(x.currentMeter,1)}</td><td>${status(x.dueState)}</td></tr>`))+`<details><summary>Add PM / WGP plan</summary><div class="grid3 topgap"><label>Equipment *<select id="ppAsset">${assetOptions()}</select></label><label>Activity<select id="ppActivity"><option>PM</option><option>WASHING</option><option>GREASING</option><option>INSPECTION</option></select></label><label>Plan Name *<input id="ppName" placeholder="Weekly Greasing"></label><label>Basis<select id="ppBasis"><option>DAYS</option><option>HMR</option><option>KMR</option><option>WHICHEVER_FIRST</option></select></label><label>Meter Interval<input id="ppInterval" type="number" inputmode="decimal"></label><label>Calendar Days<input id="ppDays" type="number" inputmode="decimal" value="7"></label><label>Warning Before<input id="ppWarn" type="number" inputmode="decimal"></label></div><div class="btnrow"><button class="btn primary" onclick="savePmPlan()">Save Plan</button></div></details>`)
}
async function renderDefConfig(){
  const sum=await api(`/api/maintenance/${siteId}/def-summary?from_date=${dateVal(new Date(Date.now()-30*86400000))}&to_date=${dateVal()}`);const alerts=new Map((sum.alerts||[]).map(x=>[x.assetId,x]));
  return panel('DEF / Urea Schedule & Consumption',table(['Equipment','DEF L','HSD L','DEF % HSD','Schedule'],(sum.rows||[]).map(x=>{const a=alerts.get(x.assetId);return `<tr><td>${esc(x.assetId)}</td><td>${fmt(x.defL,2)}</td><td>${fmt(x.hsdL,2)}</td><td>${fmt(x.defPctHsd,2)}${x.defPctHsd!=null?'%':''}</td><td>${a?`${status(a.state)}${a.remainingL!=null?`<br><span class="muted">Est. ${fmt(a.remainingL,1)} L remaining</span>`:''}`:'—'}</td></tr>`}))+`<details><summary>Configure equipment DEF schedule</summary><div class="grid3 topgap"><label>Equipment *<select id="defAsset">${assetOptions()}</select></label><label>Tank Capacity L<input id="defCap" type="number" inputmode="decimal"></label><label>Normal Issue Qty L<input id="defNormal" type="number" inputmode="decimal"></label><label>Expected Rate<input id="defRate" type="number" inputmode="decimal" step="0.001"></label><label>Rate Basis<select id="defRateBasis"><option value="PER_HOUR">Per HMR Hour</option><option value="PER_KM">Per KM</option><option value="PCT_HSD">% of HSD</option></select></label><label>Alert Level L<input id="defAlert" type="number" inputmode="decimal"></label></div><div class="btnrow"><button class="btn primary" onclick="saveDefProfile()">Save DEF Configuration</button></div></details>`)
}
function mechBars(rows,labelKey,valueKey,unit=''){rows=(rows||[]).filter(x=>Number(x[valueKey]||0)>=0);if(!rows.length)return'<div class="empty">No data in selected period.</div>';const max=Math.max(...rows.map(x=>Number(x[valueKey]||0)),1);return `<div class="mech-bars">${rows.map(x=>`<div class="mech-bar"><span>${esc(x[labelKey])}</span><div><i style="width:${Math.max(2,Number(x[valueKey]||0)/max*100)}%"></i></div><b>${fmt(x[valueKey],1)}${unit}</b></div>`).join('')}</div>`}
function mechDonut(rows){rows=(rows||[]).filter(x=>Number(x.value||0)>0);if(!rows.length)return'<div class="empty">No status data.</div>';const total=rows.reduce((a,x)=>a+Number(x.value||0),0)||1,colors=['#0f766e','#2563eb','#d97706','#dc2626','#7c3aed','#0891b2','#64748b','#16a34a'];let at=0;const stops=rows.map((x,i)=>{const a=at,b=at+Number(x.value)/total*100;at=b;return `${colors[i%colors.length]} ${a}% ${b}%`}).join(',');return `<div class="mech-donut-wrap"><div class="mech-donut" style="background:conic-gradient(${stops})"><div><b>${fmt(total)}</b><span>Equipment</span></div></div><div class="mech-donut-legend">${rows.map((x,i)=>`<div><i style="background:${colors[i%colors.length]}"></i><span>${esc(String(x.label).replaceAll('_',' '))}</span><b>${fmt(x.value)} · ${fmt(Number(x.value)/total*100,1)}%</b></div>`).join('')}</div></div>`}
function mechTrend(rows){rows=rows||[];if(!rows.length)return'<div class="empty">No breakdowns in selected period.</div>';const max=Math.max(...rows.map(x=>Number(x.breakdowns||0)),1);return `<div class="mech-trend">${rows.slice(-20).map(x=>`<div><b>${fmt(x.breakdowns)}</b><i style="height:${Math.max(5,Number(x.breakdowns||0)/max*92)}px"><span>${fmt(x.breakdowns)}</span></i><small>${esc(String(x.date).slice(5))}</small></div>`).join('')}</div>`}
function applyMechanicalDashboardFilters(){state.dashboardFilters={from:$('mdFrom')?.value||'',to:$('mdTo')?.value||'',asset:$('mdAsset')?.value||'',status:$('mdStatus')?.value||'',type:$('mdType')?.value||''};refreshDash().then(render).catch(e=>toast(e.message,'bad'))}
function resetMechanicalDashboardFilters(){state.dashboardFilters={from:'',to:'',asset:'',status:'',type:''};refreshDash().then(render).catch(e=>toast(e.message,'bad'))}
function csvCell(v){v=String(v??'');return /[",\n]/.test(v)?`"${v.replaceAll('"','""')}"`:v}
function downloadText(name,text,type){const blob=new Blob([text],{type:type||'text/plain'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function mechanicalDashboardCsv(){const d=state.dash||{},k=d.historyKpis||{},rows=[['Metric','Value'],...Object.entries(d.counts||{}),...Object.entries(k)];downloadText(`TIOM_Mechanical_Dashboard_${d.fromDate||dateVal()}_${d.toDate||dateVal()}.csv`,rows.map(r=>r.map(csvCell).join(',')).join('\n'),'text/csv')}
function mechanicalDashboardJson(){const d=state.dash||{};downloadText(`TIOM_Mechanical_Dashboard_${d.fromDate||dateVal()}_${d.toDate||dateVal()}.json`,JSON.stringify(d,null,2),'application/json')}
function printMechanicalDashboard(){window.print()}
async function shareMechanicalDashboard(){const d=state.dash||{},k=d.historyKpis||{},text=`TIOM Mechanical ${d.fromDate||''} to ${d.toDate||''}\nRunning ${d.counts?.RUNNING||0} | Available ${d.counts?.AVAILABLE||0} | BD ${d.counts?.BREAKDOWN||0}\nBreakdowns ${k.breakdowns||0} | Downtime ${fmt(k.downtimeHours,1)} h | MTTR ${fmt(k.mttrHours,1)} h`;if(navigator.share){await navigator.share({title:'TIOM Mechanical Dashboard',text});}else{await navigator.clipboard?.writeText(text);toast('Dashboard summary copied.')}}
function renderDashboard(){const d=state.dash,c=d.counts||{},hk=d.historyKpis||{},f=state.dashboardFilters||{};if(!f.from)f.from=d.fromDate||dateVal(new Date(Date.now()-29*86400000));if(!f.to)f.to=d.toDate||dateVal();const types=d.filters?.availableTypes||[],statuses=d.filters?.availableStatuses||[];const assetOpts=`<option value="">All equipment</option>${(state.dash?.allAssets||state.dash?.assets||[]).map(x=>`<option value="${esc(x.assetId)}" ${f.asset===x.assetId?'selected':''}>${esc(x.display)} · ${esc(x.type||'')}</option>`).join('')}`;const filter=`<div class="mech-dashboard-toolbar"><label>From<input id="mdFrom" type="date" value="${esc(f.from)}"></label><label>To<input id="mdTo" type="date" value="${esc(f.to)}"></label><label>Equipment<select id="mdAsset">${assetOpts}</select></label><label>Type<select id="mdType"><option value="">All types</option>${types.map(x=>`<option value="${esc(x)}" ${f.type===x?'selected':''}>${esc(x)}</option>`).join('')}</select></label><label>Status<select id="mdStatus"><option value="">All status</option>${statuses.map(x=>`<option value="${esc(x)}" ${f.status===x?'selected':''}>${esc(String(x).replaceAll('_',' '))}</option>`).join('')}</select></label><button class="btn primary" onclick="applyMechanicalDashboardFilters()">Apply</button><button class="btn ghost" onclick="resetMechanicalDashboardFilters()">Reset</button><div class="mech-export-actions"><button class="btn secondary" onclick="mechanicalDashboardCsv()">CSV</button><button class="btn secondary" onclick="mechanicalDashboardJson()">JSON</button><button class="btn secondary" onclick="printMechanicalDashboard()">Print / PDF</button><button class="btn secondary" onclick="shareMechanicalDashboard()">Share</button></div></div>`;const cards=[['TOTAL','Total'],['RUNNING','Running'],['AVAILABLE','Available'],['BREAKDOWN','BD'],['UNDER_MAINTENANCE','Maintenance'],['UNDER_SERVICE','Service'],['PM','PM'],['IDLE','Idle'],['DEF_DUE','DEF Due']];const kp=`<div class="kpis">${cards.map(([k,l])=>`<div class="kpi ${k==='BREAKDOWN'||k==='DEF_DUE'&&c[k]?'bad':k==='RUNNING'||k==='AVAILABLE'?'good':''}" ${k==='DEF_DUE'?'':`onclick="filterAssetStatus('${k==='TOTAL'?'':k}')"`}><span>${l}</span><b>${fmt(c[k]||0)}</b><small>${k==='DEF_DUE'?'Schedule alerts':'Click to filter'}</small></div>`).join('')}</div>`;const history=`<div class="mech-history-kpis">${[['Breakdowns',hk.breakdowns],['Open BD',hk.openBreakdowns],['Downtime',fmt(hk.downtimeHours,1)+' h'],['MTTR',fmt(hk.mttrHours,1)+' h'],['Services',hk.services],['PM Completed',hk.pmCompleted],['DEF',fmt(hk.defLitres,1)+' L'],['Spare Cost','₹ '+fmt(hk.spareCost,0)],['Lube Cost','₹ '+fmt(hk.lubricantCost,0)]].map(x=>`<div><span>${x[0]}</span><b>${x[1]??0}</b></div>`).join('')}</div>`;const alerts=[...(d.serviceDue||[]).map(x=>({...x,kind:'Service'})),...(d.componentDue||[]).map(x=>({...x,kind:'Component'})),...(d.pmDue||[]).map(x=>({...x,kind:x.activity||'PM'})),...(d.defAlerts||[]).filter(x=>x.state!=='OK').map(x=>({...x,name:'DEF / Urea',kind:x.basis==='PCT_HSD'?'DEF · % HSD':'DEF · '+String(x.basis||'Schedule').replaceAll('_',' ')}))];const ar=alerts.slice(0,15).map(x=>`<div class="alert"><div><b>${esc(x.assetId||'Equipment group')} · ${esc(x.name)}</b><small>${esc(x.kind)} ${x.nextDueMeter!=null?'· Est. due '+fmt(x.nextDueMeter,1):''} ${x.nextDueAt?'· '+esc(x.nextDueAt):''} ${x.remainingL!=null?'· Est. remaining '+fmt(x.remainingL,1)+' L':''}</small></div>${status(x.state)}</div>`).join('')||'<div class="empty">No maintenance due alerts configured yet.</div>';const statusRows=Object.entries(c).filter(([k])=>!['TOTAL','DEF_DUE'].includes(k)).map(([label,value])=>({label,value}));const dueRows=[{label:'Service',value:(d.serviceDue||[]).length},{label:'Components',value:(d.componentDue||[]).length},{label:'PM / WGP',value:(d.pmDue||[]).length},{label:'DEF',value:(d.defAlerts||[]).filter(x=>x.state!=='OK').length}];return filter+kp+history+`<div class="grid2">${panel('Equipment Status Distribution',mechDonut(statusRows))}${panel('Maintenance Due / Overdue',mechBars(dueRows,'label','value',''))}</div><div class="grid2">${panel('Breakdown Trend',mechTrend(d.breakdownTrend||[]))}${panel('Due / Overdue Alerts',`<div class="alert-list">${ar}</div>`)}</div>${panel('Live Equipment Status',assetStatusTable(d.assets||[]))}`}

function assetStatusTable(rows){return table(['Equipment','Type','Status','Shift data','Location','HMR/KMR','Since'],rows.map(x=>`<tr class="asset-row" data-status="${esc(x.status)}"><td><b>${esc(x.display)}</b><br><span class="muted">${esc(x.assetId)}</span></td><td>${esc(x.type||'—')}</td><td>${status(x.status)}</td><td>${esc(x.operatorId||'—')}</td><td>${esc(x.locationId||'—')}</td><td>${esc(x.meterType||'')} ${fmt(x.meterReading,1)}</td><td>${x.statusSince?new Date(x.statusSince).toLocaleString('en-IN'):'—'}</td></tr>`))}
function filterAssetStatus(s){document.querySelectorAll('.asset-row').forEach(r=>r.style.display=!s||r.dataset.status===s?'':'none')}
async function renderBreakdowns(){const rows=await api(`/api/maintenance/${siteId}/breakdowns?from_date=${dateVal(new Date(Date.now()-30*86400000))}&to_date=${dateVal()}`);return panel('Report Breakdown',`<div class="form-grid"><div class="field"><span>Equipment *</span><select id="bdAsset">${assetOptions()}</select></div><div class="field"><span>Problem Category *</span><select id="bdCat"><option>MECHANICAL</option><option>ENGINE</option><option>HYDRAULIC</option><option>ELECTRICAL</option><option>TYRE</option><option>BRAKE</option><option>OTHER</option></select></div><div class="field wide"><span>Problem *</span><input id="bdProblem" placeholder="Short problem description"></div><div class="field wide"><span>Remarks</span><input id="bdRemarks" placeholder="Optional"></div></div><div class="actions"><button class="btn primary" onclick="saveBreakdown()">Report Breakdown</button><span class="muted">Date, time, shift, operator, location and latest HMR/KMR are automatic.</span></div>`)+panel('Recent Breakdowns',table(['BD No.','Equipment','Reported','Problem','Meter','Status','Downtime','Action'],rows.map(x=>`<tr><td>${esc(x.breakdownId)}</td><td>${esc(x.assetId)}</td><td>${new Date(x.reportedAt).toLocaleString('en-IN')}</td><td><b>${esc(x.problemCategory)}</b><br>${esc(x.problem)}</td><td>${esc(x.meterType||'')} ${fmt(x.meterReading,1)}</td><td>${status(x.status)}</td><td>${fmt(x.downtimeHours,2)}</td><td>${['OPEN','IN_PROGRESS'].includes(x.status)?`<button class="btn small primary" onclick="closeBreakdown('${esc(x.breakdownId)}')">Release</button>`:''}</td></tr>`)))}
async function saveBreakdown(){try{const asset=$('bdAsset').value,problem=$('bdProblem').value.trim();if(!asset||!problem)throw new Error('Choose equipment and enter problem.');const r=await api(`/api/maintenance/${siteId}/breakdowns`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({assetId:asset,problemCategory:$('bdCat').value,problem,remarks:$('bdRemarks').value.trim()||null})});toast(`BD created · ${r.breakdownId}`);await refreshDash();render()}catch(e){toast(e.message,'bad')}}
async function closeBreakdown(id){const action=prompt('Action taken / repair completed:');if(!action)return;const diagnosis=prompt('Diagnosis (optional):')||null;try{await api(`/api/maintenance/${siteId}/breakdowns/${id}/close`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({actionTaken:action,diagnosis})});toast('Machine released');await refreshDash();render()}catch(e){toast(e.message,'bad')}}
async function renderJobs(){const rows=await api(`/api/maintenance/${siteId}/job-cards`);return panel('New Job Card',`<div class="form-grid"><div class="field"><span>Equipment *</span><select id="jcAsset">${assetOptions()}</select></div><div class="field"><span>Job Type *</span><select id="jcType"><option>GENERAL</option><option>SERVICE</option><option>PM</option><option>TYRE</option><option>INSPECTION</option></select></div><div class="field wide"><span>Complaint / Work Required</span><input id="jcComplaint"></div></div><div class="actions"><button class="btn primary" onclick="saveJob()">Create Job Card</button></div>`)+panel('Job Cards',table(['Job Card','Equipment','Type','Opened','Status','Complaint','Mechanic','Action'],rows.map(x=>`<tr><td>${esc(x.jobCardId)}</td><td>${esc(x.assetId)}</td><td>${esc(x.jobType)}</td><td>${new Date(x.openedAt).toLocaleString('en-IN')}</td><td>${status(x.status)}</td><td>${esc(x.complaint||'—')}</td><td>${esc(x.mechanicId||'—')}</td><td>${x.status==='OPEN'?`<button class="btn small" onclick="jobStatus('${esc(x.jobCardId)}','IN_PROGRESS')">Start</button>`:''}${['OPEN','IN_PROGRESS','COMPLETED'].includes(x.status)?` <button class="btn small primary" onclick="releaseJob('${esc(x.jobCardId)}')">Complete</button>`:''}</td></tr>`)))}
async function saveJob(){try{if(!$('jcAsset').value)throw new Error('Choose equipment.');await api(`/api/maintenance/${siteId}/job-cards`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({assetId:$('jcAsset').value,jobType:$('jcType').value,complaint:$('jcComplaint').value.trim()||null})});toast('Job card created');await refreshDash();render()}catch(e){toast(e.message,'bad')}}
async function jobStatus(id,s){try{await api(`/api/maintenance/${siteId}/job-cards/${id}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({status:s})});toast('Job updated');await refreshDash();render()}catch(e){toast(e.message,'bad')}}
async function releaseJob(id){const action=prompt('Action taken:');if(!action)return;const cause=prompt('Root cause (optional):')||null;try{await api(`/api/maintenance/${siteId}/job-cards/${id}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({status:'RELEASED',actionTaken:action,rootCause:cause})});toast('Job completed');await refreshDash();render()}catch(e){toast(e.message,'bad')}}
async function renderService(){state.services=await api(`/api/maintenance/${siteId}/service-plans`);return panel('Service Plans',table(['Equipment','Service','Basis','Last','Current','Next Due','Balance','Status','Action'],state.services.map(x=>`<tr><td>${esc(x.assetId||x.equipmentType||'Group')}</td><td>${esc(x.serviceName)}</td><td>${esc(x.scheduleBasis)}</td><td>${x.lastMeter!=null?fmt(x.lastMeter,1):esc(x.lastServiceAt||'—')}</td><td>${fmt(x.currentMeter,1)}</td><td>${x.nextDueMeter!=null?fmt(x.nextDueMeter,1):esc(x.nextDueAt||'—')}</td><td>${fmt(x.remaining,1)}</td><td>${status(x.dueState)}</td><td>${x.assetId?`<button class="btn small primary" onclick="completeService('${esc(x.planId)}')">Complete</button>`:''}</td></tr>`)))+`<details><summary>Add / configure service plan</summary><div class="form-grid" style="margin-top:9px"><div class="field"><span>Equipment *</span><select id="svAsset">${assetOptions()}</select></div><div class="field"><span>Service Name *</span><input id="svName" placeholder="500 HMR Service"></div><div class="field"><span>Basis *</span><select id="svBasis"><option>HMR</option><option>KMR</option><option>DAYS</option><option>WHICHEVER_FIRST</option></select></div><div class="field"><span>Meter Interval</span><input id="svInterval" type="number" inputmode="decimal" step="0.001"></div><div class="field"><span>Calendar Days</span><input id="svDays" type="number" inputmode="decimal"></div><div class="field"><span>Warning Before</span><input id="svWarn" type="number" inputmode="decimal" step="0.001"></div><div class="field"><span>Last Meter</span><input id="svLastMeter" type="number" inputmode="decimal" step="0.001"></div><div class="field"><span>Last Service Date</span><input id="svLastDate" type="date"></div></div><div class="actions"><button class="btn primary" onclick="saveServicePlan()">Save Plan</button></div></details>`}
async function saveServicePlan(){try{const b=$('svBasis').value;const body={assetId:$('svAsset').value||null,serviceName:$('svName').value.trim(),scheduleBasis:b,intervalValue:$('svInterval').value||null,calendarIntervalDays:$('svDays').value?+$('svDays').value:null,warningValue:$('svWarn').value||null,lastMeter:$('svLastMeter').value||null,lastServiceAt:$('svLastDate').value||null};if(!body.assetId||!body.serviceName)throw new Error('Choose equipment and service name.');await api(`/api/maintenance/${siteId}/service-plans`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});toast('Service plan saved');await refreshDash();render()}catch(e){toast(e.message,'bad')}}
async function completeService(id){try{await api(`/api/maintenance/${siteId}/service-plans/${id}/complete`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({servicedAt:nowLocal(),remarks:'Completed from Mechanical module'})});toast('Service completed and next due recalculated');await refreshDash();render()}catch(e){toast(e.message,'bad')}}
async function loadComponents(){state.components=await api(`/api/maintenance/${siteId}/components`);state.componentSchedules=await api(`/api/maintenance/${siteId}/component-schedules`)}
async function renderComponents(){await loadComponents();const masters=table(['Component','Category','Part No.','Unit','Store Link'],state.components.map(x=>`<tr><td>${esc(x.componentName)}</td><td>${esc(x.category||'—')}</td><td>${esc(x.partNumber||'—')}</td><td>${esc(x.unit)}</td><td>${esc(x.storeItemId||'—')}</td></tr>`));const schedules=table(['Equipment','Component','Basis','Interval','Current','Next Due','Balance','Status','Action'],state.componentSchedules.map(x=>`<tr><td>${esc(x.assetId||x.equipmentType||'Group')}</td><td>${esc(x.componentName)}</td><td>${esc(x.scheduleBasis)}</td><td>${fmt(x.intervalValue,1)}</td><td>${fmt(x.currentMeter,1)}</td><td>${x.nextDueMeter!=null?fmt(x.nextDueMeter,1):esc(x.nextDueAt||'—')}</td><td>${fmt(x.remaining,1)}</td><td>${status(x.dueState)}</td><td>${x.assetId?`<button class="btn small primary" onclick="changeComponent('${esc(x.scheduleId)}')">Changed</button>`:''}</td></tr>`));return panel('Component Change Schedules',schedules+`<details><summary>Add component schedule</summary><div class="form-grid" style="margin-top:9px"><div class="field"><span>Equipment *</span><select id="csAsset">${assetOptions()}</select></div><div class="field"><span>Component *</span><select id="csComponent">${componentOptions()}</select></div><div class="field"><span>Basis</span><select id="csBasis"><option>HMR</option><option>KMR</option><option>DAYS</option><option>WHICHEVER_FIRST</option></select></div><div class="field"><span>Interval</span><input id="csInterval" type="number" inputmode="decimal" step="0.001"></div><div class="field"><span>Calendar Days</span><input id="csDays" type="number" inputmode="decimal"></div><div class="field"><span>Warning Before</span><input id="csWarn" type="number" inputmode="decimal" step="0.001"></div><div class="field"><span>Required Qty</span><input id="csQty" type="number" inputmode="decimal" step="0.001" value="1"></div><div class="field"><span>Last Changed Meter</span><input id="csLast" type="number" inputmode="decimal" step="0.001"></div></div><div class="actions"><button class="btn primary" onclick="saveComponentSchedule()">Save Schedule</button></div></details>`)+panel('Component Master',masters+`<details><summary>Add component / filter / oil / spare</summary><div class="form-grid" style="margin-top:9px"><div class="field"><span>Component Name *</span><input id="cmName" placeholder="Engine Oil Filter"></div><div class="field"><span>Category</span><input id="cmCat" placeholder="FILTER"></div><div class="field"><span>Part No.</span><input id="cmPart"></div><div class="field"><span>Unit</span><input id="cmUnit" value="NOS"></div><div class="field"><span>Store Item ID</span><input id="cmStore"></div></div><div class="actions"><button class="btn primary" onclick="saveComponent()">Add Component</button></div></details>`)}
async function saveComponent(){try{if(!$('cmName').value.trim())throw new Error('Enter component name.');await api(`/api/maintenance/${siteId}/components`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({componentName:$('cmName').value.trim(),category:$('cmCat').value.trim()||null,partNumber:$('cmPart').value.trim()||null,unit:$('cmUnit').value.trim()||'NOS',storeItemId:$('cmStore').value.trim()||null})});toast('Component added');render()}catch(e){toast(e.message,'bad')}}
async function saveComponentSchedule(){try{const body={assetId:$('csAsset').value||null,componentId:$('csComponent').value,scheduleBasis:$('csBasis').value,intervalValue:$('csInterval').value||null,calendarIntervalDays:$('csDays').value?+$('csDays').value:null,warningValue:$('csWarn').value||null,requiredQty:$('csQty').value||1,lastMeter:$('csLast').value||null};if(!body.assetId||!body.componentId)throw new Error('Choose equipment and component.');await api(`/api/maintenance/${siteId}/component-schedules`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});toast('Component schedule saved');await refreshDash();render()}catch(e){toast(e.message,'bad')}}
async function changeComponent(id){try{await api(`/api/maintenance/${siteId}/component-schedules/${id}/change`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({changedAt:nowLocal(),remarks:'Changed from Mechanical module'})});toast('Component changed; spare usage and next due updated');await refreshDash();render()}catch(e){toast(e.message,'bad')}}
async function renderPm(){state.pmPlans=await api(`/api/maintenance/${siteId}/pm-plans`);const execs=await api(`/api/maintenance/${siteId}/pm-executions?from_date=${dateVal(new Date(Date.now()-30*86400000))}&to_date=${dateVal()}`);return panel('Quick PM / Washing / Greasing Completion',`<div class="form-grid"><div class="field"><span>Equipment *</span><select id="pmAsset">${assetOptions()}</select></div><div class="field"><span>Activity *</span><select id="pmActivity"><option>PM</option><option>WASHING</option><option>GREASING</option><option>INSPECTION</option></select></div><div class="field"><span>Linked Plan</span><select id="pmPlan"><option value="">None</option>${state.pmPlans.map(x=>`<option value="${esc(x.pmPlanId)}">${esc(x.planName)} · ${esc(x.assetId||'Group')}</option>`).join('')}</select></div><div class="field"><span>Result</span><select id="pmResult"><option>COMPLETE</option><option>PASS</option><option>FAIL</option></select></div><div class="field wide"><span>Remarks</span><input id="pmRemarks"></div></div><div class="actions"><button class="btn primary" onclick="savePmExecution()">Complete Activity</button><span class="muted">Latest HMR/KMR is reused automatically.</span></div>`)+panel('PM / WGP Plans',table(['Equipment','Activity','Plan','Basis','Next Due','Current','Status'],state.pmPlans.map(x=>`<tr><td>${esc(x.assetId||x.equipmentType||'Group')}</td><td>${esc(x.activity)}</td><td>${esc(x.planName)}</td><td>${esc(x.scheduleBasis)}</td><td>${x.nextDueMeter!=null?fmt(x.nextDueMeter,1):esc(x.nextDueAt||'—')}</td><td>${fmt(x.currentMeter,1)}</td><td>${status(x.dueState)}</td></tr>`))+`<details><summary>Add PM/WGP plan</summary><div class="form-grid" style="margin-top:9px"><div class="field"><span>Equipment *</span><select id="ppAsset">${assetOptions()}</select></div><div class="field"><span>Activity</span><select id="ppActivity"><option>PM</option><option>WASHING</option><option>GREASING</option><option>INSPECTION</option></select></div><div class="field"><span>Plan Name *</span><input id="ppName" placeholder="Weekly Greasing"></div><div class="field"><span>Basis</span><select id="ppBasis"><option>DAYS</option><option>HMR</option><option>KMR</option><option>WHICHEVER_FIRST</option></select></div><div class="field"><span>Meter Interval</span><input id="ppInterval" type="number" inputmode="decimal"></div><div class="field"><span>Calendar Days</span><input id="ppDays" type="number" inputmode="decimal" value="7"></div><div class="field"><span>Warning Before</span><input id="ppWarn" type="number" inputmode="decimal"></div></div><div class="actions"><button class="btn primary" onclick="savePmPlan()">Save Plan</button></div></details>`)+panel('Recent PM / WGP Completion',table(['Equipment','Activity','Completed','Meter','Result','Remarks'],execs.map(x=>`<tr><td>${esc(x.assetId)}</td><td>${esc(x.activity)}</td><td>${new Date(x.completedAt).toLocaleString('en-IN')}</td><td>${esc(x.meterType||'')} ${fmt(x.meterReading,1)}</td><td>${status(x.result)}</td><td>${esc(x.remarks||'—')}</td></tr>`)))}
async function savePmPlan(){try{const body={assetId:$('ppAsset').value||null,activity:$('ppActivity').value,planName:$('ppName').value.trim(),scheduleBasis:$('ppBasis').value,intervalValue:$('ppInterval').value||null,calendarIntervalDays:$('ppDays').value?+$('ppDays').value:null,warningValue:$('ppWarn').value||null,checklist:[]};if(!body.assetId||!body.planName)throw new Error('Choose equipment and enter plan name.');await api(`/api/maintenance/${siteId}/pm-plans`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});toast('PM plan saved');await refreshDash();render()}catch(e){toast(e.message,'bad')}}
async function savePmExecution(){try{if(!$('pmAsset').value)throw new Error('Choose equipment.');await api(`/api/maintenance/${siteId}/pm-executions`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({assetId:$('pmAsset').value,activity:$('pmActivity').value,pmPlanId:$('pmPlan').value||null,result:$('pmResult').value,remarks:$('pmRemarks').value.trim()||null})});toast('PM/WGP activity completed');await refreshDash();render()}catch(e){toast(e.message,'bad')}}
async function renderDef(){const from=dateVal(new Date(Date.now()-30*86400000)),to=dateVal();const [rows,sum]=await Promise.all([api(`/api/maintenance/${siteId}/def?from_date=${from}&to_date=${to}`),api(`/api/maintenance/${siteId}/def-summary?from_date=${from}&to_date=${to}`)]);const alerts=new Map((sum.alerts||[]).map(x=>[x.assetId,x]));const summary=table(['Equipment','DEF L','HSD L','DEF % HSD','Schedule'],(sum.rows||[]).map(x=>{const a=alerts.get(x.assetId);return `<tr><td>${esc(x.assetId)}</td><td>${fmt(x.defL,2)}</td><td>${fmt(x.hsdL,2)}</td><td>${fmt(x.defPctHsd,2)}${x.defPctHsd!=null?'%':''}</td><td>${a?`${status(a.state)}${a.remainingL!=null?`<br><span class="muted">Est. ${fmt(a.remainingL,1)} L remaining</span>`:''}`:'—'}</td></tr>`}));return panel('DEF / Urea Issue',`<div class="form-grid"><div class="field"><span>Equipment *</span><select id="defAsset">${assetOptions()}</select></div><div class="field"><span>DEF Quantity (L) *</span><input id="defQty" type="number" inputmode="decimal" step="0.001"></div><div class="field"><span>Issue Slip / Reference</span><input id="defRef"></div><div class="field"><span>Remarks</span><input id="defRemarks"></div></div><div class="actions"><button class="btn primary" onclick="saveDef()">Save DEF Issue</button><span class="muted">Shift, operator and latest HMR/KMR are automatic.</span></div><details><summary>Configure DEF capacity / normal issue schedule</summary><div class="form-grid" style="margin-top:9px"><div class="field"><span>Tank Capacity L</span><input id="defCap" type="number" inputmode="decimal"></div><div class="field"><span>Normal Issue Qty L</span><input id="defNormal" type="number" inputmode="decimal"></div><div class="field"><span>Expected Rate</span><input id="defRate" type="number" inputmode="decimal" step="0.001"></div><div class="field"><span>Rate Basis</span><select id="defRateBasis"><option value="PER_HOUR">Per HMR Hour</option><option value="PER_KM">Per KM</option><option value="PCT_HSD">% of HSD</option></select></div><div class="field"><span>Alert Level L</span><input id="defAlert" type="number" inputmode="decimal"></div></div><div class="actions"><button class="btn" onclick="saveDefProfile()">Save DEF Configuration</button></div></details>`)+panel(`DEF / HSD Summary · ${from} to ${to}`,summary)+panel('Recent DEF / Urea',table(['Date','Shift','Equipment','Qty L','Meter','Operator','Reference'],rows.map(x=>`<tr><td>${esc(x.operatingDate)}</td><td>${esc(x.shift||'—')}</td><td>${esc(x.assetId)}</td><td>${fmt(x.quantityL,2)}</td><td>${esc(x.meterType||'')} ${fmt(x.meterReading,1)}</td><td>${esc(x.operatorId||'—')}</td><td>${esc(x.issueReference||'—')}</td></tr>`)))}
async function saveDef(){try{if(!$('defAsset').value||!+$('defQty').value)throw new Error('Choose equipment and enter quantity.');await api(`/api/maintenance/${siteId}/def`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({assetId:$('defAsset').value,quantityL:$('defQty').value,issueReference:$('defRef').value.trim()||null,remarks:$('defRemarks').value.trim()||null})});toast('DEF issue saved');render()}catch(e){toast(e.message,'bad')}}
async function saveDefProfile(){try{if(!$('defAsset').value)throw new Error('Choose equipment first.');await api(`/api/maintenance/${siteId}/def-profile`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({assetId:$('defAsset').value,tankCapacityL:$('defCap').value||null,normalIssueQtyL:$('defNormal').value||null,expectedRate:$('defRate').value||null,rateBasis:$('defRateBasis').value,alertLevelL:$('defAlert').value||null})});toast('DEF configuration saved')}catch(e){toast(e.message,'bad')}}
async function renderSpares(){const [s,l]=await Promise.all([api(`/api/maintenance/${siteId}/spares?from_date=${dateVal(new Date(Date.now()-30*86400000))}&to_date=${dateVal()}`),api(`/api/maintenance/${siteId}/lubricants?from_date=${dateVal(new Date(Date.now()-30*86400000))}&to_date=${dateVal()}`)]);return `<div class="grid2">${panel('Spare Consumption',`<div class="form-grid two"><div class="field"><span>Equipment *</span><select id="spAsset">${assetOptions()}</select></div><div class="field"><span>Part / Spare *</span><input id="spDesc"></div><div class="field"><span>Qty *</span><input id="spQty" type="number" inputmode="decimal" step="0.001"></div><div class="field"><span>Unit</span><input id="spUnit" value="NOS"></div><div class="field"><span>Store Issue Ref</span><input id="spRef"></div><div class="field"><span>Job Card</span><input id="spJob"></div></div><div class="actions"><button class="btn primary" onclick="saveSpare()">Save Spare Use</button></div>${table(['Equipment','Part','Qty','Job','Store Ref'],s.slice(0,50).map(x=>`<tr><td>${esc(x.assetId)}</td><td>${esc(x.description)}</td><td>${fmt(x.quantity,2)} ${esc(x.unit)}</td><td>${esc(x.jobCardId||'—')}</td><td>${esc(x.storeIssueReference||'—')}</td></tr>`))}`)}${panel('Lubricant Consumption',`<div class="form-grid two"><div class="field"><span>Equipment *</span><select id="luAsset">${assetOptions()}</select></div><div class="field"><span>Lubricant *</span><select id="luType"><option>ENGINE OIL</option><option>HYDRAULIC OIL</option><option>TRANSMISSION OIL</option><option>GEAR OIL</option><option>GREASE</option><option>COOLANT</option><option>OTHER</option></select></div><div class="field"><span>Qty *</span><input id="luQty" type="number" inputmode="decimal" step="0.001"></div><div class="field"><span>Unit</span><input id="luUnit" value="L"></div><div class="field"><span>Job Card</span><input id="luJob"></div></div><div class="actions"><button class="btn primary" onclick="saveLube()">Save Lubricant Use</button></div>${table(['Equipment','Lubricant','Qty','Job','Used'],l.slice(0,50).map(x=>`<tr><td>${esc(x.assetId)}</td><td>${esc(x.lubricantType)}</td><td>${fmt(x.quantity,2)} ${esc(x.unit)}</td><td>${esc(x.jobCardId||'—')}</td><td>${new Date(x.usedAt).toLocaleDateString('en-IN')}</td></tr>`))}`)}</div>`}
async function saveSpare(){try{if(!$('spAsset').value||!$('spDesc').value.trim()||!+$('spQty').value)throw new Error('Equipment, part and quantity are required.');await api(`/api/maintenance/${siteId}/spares`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({assetId:$('spAsset').value,description:$('spDesc').value.trim(),quantity:$('spQty').value,unit:$('spUnit').value||'NOS',storeIssueReference:$('spRef').value.trim()||null,jobCardId:$('spJob').value.trim()||null})});toast('Spare consumption saved');render()}catch(e){toast(e.message,'bad')}}
async function saveLube(){try{if(!$('luAsset').value||!+$('luQty').value)throw new Error('Equipment and quantity are required.');await api(`/api/maintenance/${siteId}/lubricants`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({assetId:$('luAsset').value,lubricantType:$('luType').value,quantity:$('luQty').value,unit:$('luUnit').value||'L',jobCardId:$('luJob').value.trim()||null})});toast('Lubricant consumption saved');render()}catch(e){toast(e.message,'bad')}}
async function renderTyres(){state.tyres=await api(`/api/maintenance/${siteId}/tyres`);return panel('Tyre Register',table(['Serial','Brand','Size','Status','Equipment','Position','Fit KMR'],state.tyres.map(x=>`<tr><td>${esc(x.serialNo)}</td><td>${esc(x.brand||'—')}</td><td>${esc(x.tyreSize||'—')}</td><td>${status(x.status)}</td><td>${esc(x.assetId||'—')}</td><td>${esc(x.position||'—')}</td><td>${fmt(x.fitKmr,1)}</td></tr>`))+`<div class="grid2" style="margin-top:12px"><div><h3>Add Tyre</h3><div class="form-grid two"><div class="field"><span>Serial No. *</span><input id="tySerial"></div><div class="field"><span>Brand</span><input id="tyBrand"></div><div class="field"><span>Size</span><input id="tySize"></div><div class="field"><span>Cost</span><input id="tyCost" type="number" inputmode="decimal"></div></div><div class="actions"><button class="btn" onclick="saveTyre()">Add Tyre</button></div></div><div><h3>Fit Tyre</h3><div class="form-grid two"><div class="field"><span>Tyre *</span><select id="tyFitId">${tyreOptions()}</select></div><div class="field"><span>Equipment *</span><select id="tyAsset">${assetOptions()}</select></div><div class="field"><span>Axle</span><input id="tyAxle"></div><div class="field"><span>Position</span><input id="tyPos"></div></div><div class="actions"><button class="btn primary" onclick="fitTyre()">Fit Tyre</button></div></div></div>`)}
async function saveTyre(){try{if(!$('tySerial').value.trim())throw new Error('Enter tyre serial number.');await api(`/api/maintenance/${siteId}/tyres`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({serialNo:$('tySerial').value.trim(),brand:$('tyBrand').value.trim()||null,tyreSize:$('tySize').value.trim()||null,purchaseCost:$('tyCost').value||null})});toast('Tyre added');render()}catch(e){toast(e.message,'bad')}}
async function fitTyre(){try{if(!$('tyFitId').value||!$('tyAsset').value)throw new Error('Choose tyre and equipment.');await api(`/api/maintenance/${siteId}/tyres/fit`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({tyreId:$('tyFitId').value,assetId:$('tyAsset').value,axle:$('tyAxle').value.trim()||null,position:$('tyPos').value.trim()||null})});toast('Tyre fitted using current KMR when available');render()}catch(e){toast(e.message,'bad')}}
function renderHistory(){return panel('Equipment 360°',`<div class="filters"><div class="field"><span>Equipment</span><select id="hiAsset">${assetOptions()}</select></div><div class="field"><span>From</span><input id="hiFrom" type="date" value="${dateVal(new Date(Date.now()-90*86400000))}"></div><div class="field"><span>To</span><input id="hiTo" type="date" value="${dateVal()}"></div><button class="btn primary" onclick="loadHistory()">Load History</button></div><div id="historyOut"></div>`)}
async function loadHistory(){try{if(!$('hiAsset').value)throw new Error('Choose equipment.');const d=await api(`/api/maintenance/${siteId}/history/${$('hiAsset').value}?from_date=${$('hiFrom').value}&to_date=${$('hiTo').value}`);$('historyOut').innerHTML=`<div class="history-block"><h3>${esc(d.asset.display)} · ${esc(d.asset.type||'')}</h3>${table(['Date','Shift','Meter','Opening','Closing','Usage','Source'],d.meters.map(x=>`<tr><td>${esc(x.date)}</td><td>${esc(x.shift)}</td><td>${esc(x.type)}</td><td>${fmt(x.opening,1)}</td><td>${fmt(x.closing,1)}</td><td>${fmt(x.usage,1)}</td><td>${esc(x.source)}</td></tr>`))}</div><div class="history-block"><h3>Breakdowns</h3>${table(['BD','Reported','Released','Problem','Downtime','Status'],d.breakdowns.map(x=>`<tr><td>${esc(x.breakdownId)}</td><td>${new Date(x.reportedAt).toLocaleString('en-IN')}</td><td>${x.releasedAt?new Date(x.releasedAt).toLocaleString('en-IN'):'—'}</td><td>${esc(x.problem)}</td><td>${fmt(x.downtimeHours,2)}</td><td>${status(x.status)}</td></tr>`))}</div><div class="history-block"><h3>Job Cards</h3>${table(['Job','Type','Opened','Status','Action'],d.jobCards.map(x=>`<tr><td>${esc(x.jobCardId)}</td><td>${esc(x.jobType)}</td><td>${new Date(x.openedAt).toLocaleString('en-IN')}</td><td>${status(x.status)}</td><td>${esc(x.actionTaken||'—')}</td></tr>`))}</div><div class="history-block"><h3>DEF / Urea</h3>${table(['Time','Qty L','Meter'],d.def.map(x=>`<tr><td>${new Date(x.eventAt).toLocaleString('en-IN')}</td><td>${fmt(x.quantityL,2)}</td><td>${fmt(x.meterReading,1)}</td></tr>`))}</div>`}catch(e){toast(e.message,'bad')}}
async function renderCompliance(){const rows=await api(`/api/maintenance/${siteId}/documents`);return panel('Compliance / Documents',`<div class="form-grid"><div class="field"><span>Equipment *</span><select id="coAsset">${assetOptions()}</select></div><div class="field"><span>Document Type *</span><select id="coType"><option>PUC</option><option>INSURANCE</option><option>FITNESS</option><option>PERMIT</option><option>ROAD TAX</option><option>AMC</option><option>WARRANTY</option><option>OTHER</option></select></div><div class="field"><span>Reference No.</span><input id="coRef"></div><div class="field"><span>Valid To</span><input id="coTo" type="date"></div></div><div class="actions"><button class="btn primary" onclick="saveCompliance()">Save Document</button></div>`)+panel('Expiry Status',table(['Equipment','Document','Reference','Valid To','Status'],rows.map(x=>`<tr><td>${esc(x.assetId)}</td><td>${esc(x.documentType)}</td><td>${esc(x.referenceNo||'—')}</td><td>${esc(x.validTo||'—')}</td><td>${status(x.status)}</td></tr>`)))}
async function saveCompliance(){try{if(!$('coAsset').value)throw new Error('Choose equipment.');await api(`/api/maintenance/${siteId}/documents`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({assetId:$('coAsset').value,documentType:$('coType').value,referenceNo:$('coRef').value.trim()||null,validTo:$('coTo').value||null})});toast('Document saved');render()}catch(e){toast(e.message,'bad')}}
function reportParams(){const q=new URLSearchParams({from_date:$('rpFrom').value,to_date:$('rpTo').value,report:$('rpType').value});if($('rpAsset').value)q.set('asset_id',$('rpAsset').value);return q}
function renderReports(){const start=dateVal(new Date(new Date().getFullYear(),new Date().getMonth(),1));return panel('Management Reports',`<div class="filters report-filter-grid"><div class="field"><span>From Date</span><input id="rpFrom" type="date" value="${start}"></div><div class="field"><span>To Date</span><input id="rpTo" type="date" value="${dateVal()}"></div><div class="field"><span>Equipment</span><select id="rpAsset">${assetOptions('All equipment')}</select></div><div class="field"><span>Report</span><select id="rpType"><option value="COMPLETE">Complete Mechanical MIS</option><option value="BREAKDOWN">Breakdown</option><option value="JOB_CARD">Job Cards</option><option value="DEF">DEF / Urea</option><option value="PM">PM / WGP</option><option value="SERVICE">Service History</option><option value="COMPONENTS">Component Changes</option><option value="TYRES">Tyre History</option><option value="COMPLIANCE">Compliance</option><option value="STATUS">Current Equipment Status</option><option value="SPARES">Spare Consumption</option><option value="LUBRICANTS">Lubricants</option></select></div></div><div class="report-action-row"><button class="btn primary" onclick="viewReport()">View</button><button class="btn secondary" onclick="downloadReport('xlsx')">Download Excel</button><button class="btn secondary" onclick="downloadReport('csv')">Download CSV</button><button class="btn secondary" onclick="printReport()">Print / PDF</button><button class="btn secondary" onclick="shareReport()">Share</button></div><div id="reportPreview" class="report-preview"><div class="note"><b>View before downloading.</b> Filters above apply to View, Share and downloads. Existing report types are preserved.</div></div>`)}
async function viewReport(){const box=$('reportPreview');box.innerHTML='<div class="loading">Loading report preview…</div>';try{const r=await api(`/api/maintenance/${siteId}/reports/preview?${reportParams()}`);state.reportPreview=r;box.innerHTML=`<div class="report-preview-head"><b>${esc(r.report)} · ${esc($('rpFrom').value)} → ${esc($('rpTo').value)}</b><span>${(r.rows||[]).length} rows${r.truncated?' · preview limited':''}</span></div>${table((r.columns||[]).map(esc),(r.rows||[]).map(row=>`<tr>${row.map(x=>`<td>${esc(x??'')}</td>`).join('')}</tr>`))}`;}catch(e){box.innerHTML=`<div class="bad">${esc(e.message)}</div>`}}
function downloadReport(format='xlsx'){if(format==='xlsx'){location.href=`/api/maintenance/${siteId}/reports/export.xlsx?${reportParams()}`;return}if(!state.reportPreview){viewReport().then(()=>{if(state.reportPreview)downloadReport(format)});return}const r=state.reportPreview,rows=[r.columns,...r.rows];downloadText(`TIOM_Mechanical_${r.report}_${$('rpFrom').value}_${$('rpTo').value}.csv`,rows.map(x=>x.map(csvCell).join(',')).join('\n'),'text/csv')}
function printReport(){if(!state.reportPreview){viewReport().then(()=>setTimeout(printReport,100));return}window.print()}
async function shareReport(){if(!state.reportPreview){await viewReport();if(!state.reportPreview)return}const r=state.reportPreview,rows=[r.columns,...r.rows],csv=rows.map(x=>x.map(csvCell).join(',')).join('\n'),file=new File([csv],`TIOM_Mechanical_${r.report}.csv`,{type:'text/csv'});if(navigator.share&&(!navigator.canShare||navigator.canShare({files:[file]}))){await navigator.share({title:`TIOM Mechanical ${r.report}`,text:`${$('rpFrom').value} to ${$('rpTo').value}`,files:[file]});}else{downloadText(file.name,csv,'text/csv');toast('Native sharing unavailable. CSV downloaded instead.')}}

async function mount(){
  try{state.bootstrap=window.S?.boot||null;state.ctx={siteName:'Thakurani Iron Ore Mine'};await refreshDash();await render()}
  catch(e){const out=$('mech_view');if(out)out.innerHTML=`<div class="bad"><b>Mechanical Maintenance unavailable.</b><br>${esc(e.message)}</div>`}
}
window.renderMechanical=async function(){
  if(!window.S?.boot){if(typeof window.showLogin==='function')window.showLogin(false);return}
  if(!S.boot.user.isManagement&&!S.boot.user.modules.includes('MECHANICAL')){html('app','<div class="panel"><div class="bad">Mechanical module is not assigned to your account.</div></div>');return}
  html('app',`<div id="mech_root" class="mech-erp"><div class="mech-erp-head"><div><div class="eyebrow">TIOM / MECHANICAL MAINTENANCE</div><h2 id="mech_title">Mechanical Dashboard</h2><p id="mech_subtitle" class="note">One equipment master. One transaction source. No duplicate field entry.</p></div><div id="mech_context" class="mech-context"></div></div><div id="mech_top_tabs" class="mech-top-tabs"></div><div id="mech_sub_tabs" class="mech-sub-tabs" hidden></div><div id="mech_view"><div class="loading">Loading Mechanical Maintenance…</div></div></div>`);
  await mount();
};
Object.assign(window,{quickEntryChanged,quickAssetInfo,saveQuickEntry,filterAssetStatus,saveBreakdown,closeBreakdown,saveJob,jobStatus,releaseJob,saveServicePlan,completeService,saveComponent,saveComponentSchedule,changeComponent,savePmPlan,savePmExecution,saveDef,saveDefProfile,saveSpare,saveLube,saveTyre,fitTyre,loadHistory,saveCompliance,downloadReport,viewReport,printReport,shareReport,applyMechanicalDashboardFilters,resetMechanicalDashboardFilters,mechanicalDashboardCsv,mechanicalDashboardJson,printMechanicalDashboard,shareMechanicalDashboard});
})();
